'use strict';
const $=id=>document.getElementById(id);
class LocalRecognizer {
  worker=null;pending=new Map();counter=0;
  start(){this.worker=new Worker('moonshine-worker.js?v=progress-2',{type:'module'});this.worker.onmessage=({data})=>{const pending=this.pending.get(data.id);if(!pending)return;if('progress'in data){if(data.progress?.label)$('status').textContent=data.progress.label;return;}this.pending.delete(data.id);clearTimeout(pending.timer);data.error?pending.reject(Error(data.error)):pending.resolve(data);};this.worker.onerror=()=>this.close('Moonshine worker failed. Check model downloads and browser support.');}
  request(type,samples){if(!this.worker)this.start();const id=++this.counter;return new Promise((resolve,reject)=>{const timer=setTimeout(()=>this.close('Model processing timed out. You can reload and try again.'),type==='load'?300000:60000);this.pending.set(id,{resolve,reject,timer});this.worker.postMessage({id,type,samples},samples?[samples.buffer]:[]);});}
  close(reason='Processing cancelled.'){this.worker?.terminate();this.worker=null;for(const p of this.pending.values()){clearTimeout(p.timer);p.reject(Error(reason));}this.pending.clear();}
}
const engine=new LocalRecognizer();let commands=[],ready=false,busy=false,batchCancelled=false,stream=null,recorder=null,timer=null,cancelled=false,previewUrl='',generation=0;
function controls(){for(const id of ['record','test','all','file'])$(id).disabled=!ready||busy||!commands.length;$('load').disabled=ready||busy;$('unload').disabled=!engine.worker;}
function release(){clearTimeout(timer);stream?.getTracks().forEach(t=>t.stop());stream=null;$('finish').hidden=true;$('cancel').hidden=true;$('mic-status').textContent='Microphone off.';}
function reset(){generation++;batchCancelled=true;cancelled=true;if(recorder?.state==='recording')recorder.stop();release();engine.close();ready=false;busy=false;controls();$('cancel-batch').hidden=true;$('status').textContent='Microphone off. Model unloaded.';}
async function decode(blob){if(blob.size>8e6)throw Error('Use a file below 8 MB.');const context=new AudioContext();let buffer;try{buffer=await context.decodeAudioData(await blob.arrayBuffer());}finally{await context.close();}if(buffer.duration<.04||buffer.duration>15)throw Error('Use 40 ms–15 seconds of audio.');const offline=new OfflineAudioContext(1,Math.ceil(buffer.duration*16000),16000),source=offline.createBufferSource();source.buffer=buffer;source.connect(offline.destination);source.start();return(await offline.startRendering()).getChannelData(0).slice();}
async function recognise(blob,version=generation){const samples=await decode(blob);if(version!==generation||!ready)throw Error('Processing cancelled.');const result=await engine.request('transcribe',samples);if(version!==generation)throw Error('Processing cancelled.');const command=MoonshineCommands.match(result.text,commands);$('transcript').textContent=result.text||'(No speech recognised)';$('match').textContent=command?`Matched: ${command.phrase} (${command.id})`:'No unambiguous command. Try one of the command names.';return {text:result.text,command};}
function preview(blob){if(previewUrl)URL.revokeObjectURL(previewUrl);previewUrl=URL.createObjectURL(blob);$('preview').src=previewUrl;$('preview').hidden=false;}
async function run(blob){const version=generation;busy=true;controls();$('status').textContent='Recognising locally…';try{preview(blob);await recognise(blob);if(version===generation)$('status').textContent='Finished. Microphone off.';}catch(e){if(version===generation)$('status').textContent=e.message;}finally{if(version===generation){busy=false;controls();}}}
$('load').onclick=async()=>{busy=true;controls();$('status').textContent='Loading Moonshine… First load can take a while.';const version=generation;try{if(!crossOriginIsolated)throw Error('Restart the updated workshop server: this page requires cross-origin isolation.');const loading=engine.request('load');controls();await loading;if(version===generation){ready=true;$('status').textContent='Moonshine ready. Microphone off. English Tiny Streaming model.';}}catch(e){if(version===generation){engine.close();$('status').textContent='Could not load Moonshine: '+e.message;}}finally{if(version===generation){busy=false;controls();}}};
$('unload').onclick=reset;
$('record').onclick=async()=>{busy=true;cancelled=false;controls();const version=generation;try{const captured=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true},video:false});if(version!==generation){captured.getTracks().forEach(t=>t.stop());return;}stream=captured;recorder=new MediaRecorder(stream);const pieces=[];recorder.ondataavailable=e=>{if(e.data.size)pieces.push(e.data);};recorder.onstop=()=>{const blob=new Blob(pieces,{type:recorder.mimeType});release();if(version!==generation)return;busy=false;controls();if(!cancelled)run(blob);else $('status').textContent='Recording cancelled. Nothing saved.';};recorder.onerror=()=>{cancelled=true;release();busy=false;controls();$('status').textContent='Recording failed.';};recorder.start();$('finish').hidden=false;$('cancel').hidden=false;$('mic-status').textContent='Microphone ON — recording up to 5 seconds.';timer=setTimeout(()=>{if(recorder.state==='recording')recorder.stop();},5000);}catch(e){release();busy=false;controls();$('status').textContent='Microphone unavailable: '+e.message;}};
$('finish').onclick=()=>{if(recorder?.state==='recording')recorder.stop();};$('cancel').onclick=()=>{cancelled=true;if(recorder?.state==='recording')recorder.stop();};
const catalog=MoonshineCommands.samples();for(const [i,s]of catalog.entries()){const option=document.createElement('option');option.value=i;option.textContent=s.file;$('sample').append(option);}
async function sound(sample){const response=await fetch('../voice-tour/audio/commands/'+encodeURIComponent(sample.file));if(!response.ok)throw Error('Cannot load '+sample.file);return response.blob();}
$('test').onclick=async()=>{const version=generation;busy=true;controls();try{const blob=await sound(catalog[Number($('sample').value)]);if(version===generation)await run(blob);}catch(e){if(version===generation){busy=false;controls();$('status').textContent=e.message;}}};
$('file').onchange=()=>{const file=$('file').files[0];if(file)run(file);};
$('cancel-batch').onclick=()=>{batchCancelled=true;$('summary').textContent='Finishing the current test, then stopping. Use Unload to cancel immediately.';};
$('all').onclick=async()=>{busy=true;batchCancelled=false;controls();$('results').replaceChildren();$('cancel-batch').hidden=false;const version=generation;let count=0,correct=0;
  try{for(const sample of catalog){if(batchCancelled||version!==generation)break;let result,error;try{result=await recognise(await sound(sample),version);}catch(e){error=e.message;}if(version!==generation)break;const ok=result?.command?.id===sample.expected;count++;if(ok)correct++;const tr=document.createElement('tr');for(const value of [sample.file,result?.text||error||'(No speech)',sample.expected,result?.command?.id||'—',ok?'Match':'No match']){const td=document.createElement('td');td.textContent=value;tr.append(td);}$('results').append(tr);$('summary').textContent=`${correct} / ${count} matched the expected command. This is not a confidence score.`;await new Promise(r=>setTimeout(r,0));}}finally{if(version===generation){busy=false;controls();$('cancel-batch').hidden=true;$('status').textContent=batchCancelled?'Batch stopped. Microphone off.':'Batch finished. Microphone off.';}}};
addEventListener('pagehide',reset);document.addEventListener('visibilitychange',()=>{if(document.hidden)reset();});
fetch('../audio-tour-v2/commands.json').then(r=>{if(!r.ok)throw Error('Cannot load command mappings.');return r.json();}).then(data=>{commands=data.commands;controls();}).catch(e=>{$('status').textContent=e.message;});controls();
